#!/usr/bin/env python3
"""Regenerates vesper/src/static_table.ves and vesper/src/huffman_codes.ves.

Usage: gen_tables.py RFC9204_MD H2_HUFFMAN_TABLE_RS CRATE_DIR

RFC9204_MD is rfc9204.md from github.com/quicwg/base-drafts (main);
H2_HUFFMAN_TABLE_RS is src/hpack/huffman/table.rs of the h2 0.4.12 crate.
Then run `vesper fmt` on both files.
"""
import re
import sys

rfc, h2, crate = sys.argv[1:4]
rows = []
on = False
for line in open(rfc):
    if line.startswith("# Static Table"):
        on = True
    if on and line.startswith("{: title"):
        break
    m = re.match(r"\|\s*(\d+)\s*\|\s*(\S+)\s*\|(.*)\|\s*$", line) if on else None
    if m:
        # Undo Markdown escapes such as \* and \'.
        value = re.sub(r"\\(.)", r"\1", m.group(3).strip())
        rows.append((int(m.group(1)), m.group(2), value))
assert [r[0] for r in rows] == list(range(99)), len(rows)


def lit(s):
    return s.replace("\\", "\\\\").replace('"', '\\"')


def write_static(crate, rows):
    out = [
        "// Generated by tests/fixtures/gen_tables.py from the RFC 9204 text.",
        "// Do not edit by hand.",
        "",
        "// The QPACK static table (RFC 9204 Appendix A): the names and values",
        "// concatenated, and the end of each name and value (two per index).",
        "pub fn static_bytes() -> ChunkSeq[u8] {",
        "    let mut b = ChunkSeq::with_capacity[u8](%d);" % sum(len(n) + len(v) for n, v in rows),
    ]
    for n, v in rows:
        out.append(f'    b.extend(in "{lit(n)}".as_bytes());')
        if v:
            out.append(f'    b.extend(in "{lit(v)}".as_bytes());')
    out += ["    b", "}", "", "pub fn static_ends() -> ChunkSeq[u64] {"]
    out.append("    let mut e = ChunkSeq::with_capacity[u64](198);")
    at = 0
    for n, v in rows:
        at += len(n)
        out.append(f"    e.push({at});")
        at += len(v)
        out.append(f"    e.push({at});")
    out += ["    e", "}", ""]
    open(crate + "/vesper/src/static_table.ves", "w").write("\n".join(out))


def write_huffman(crate, codes):
    out = [
        "// Generated by tests/fixtures/gen_tables.py from the h2 0.4.12 crate's",
        "// ENCODE_TABLE. Do not edit by hand.",
        "",
        "// The HPACK Huffman code (RFC 7541 Appendix B): `bit length << 32 | code`",
        "// per symbol, symbol 256 being EOS.",
        "pub fn huffman_codes() -> ChunkSeq[u64] {",
        "    let mut c = ChunkSeq::with_capacity[u64](257);",
    ]
    out += [f"    c.push({(l << 32) | v});" for l, v in codes]
    out += ["    c", "}", ""]
    open(crate + "/vesper/src/huffman_codes.ves", "w").write("\n".join(out))


write_static(crate, [(n, v) for _, n, v in rows])

txt = open(h2).read()
enc = txt.split("ENCODE_TABLE")[1].split("];")[0]
pairs = re.findall(r"\((\d+),\s*(0x[0-9a-f_]+)\)", enc)
assert len(pairs) == 257
write_huffman(crate, [(int(n), int(b.replace("_", ""), 16)) for n, b in pairs])
